changed=[]
for rel,repls in REPAIRS.items():
    p=ROOT/rel
    text=p.read_text(encoding='utf-8')
    original=text
    for old,new in repls:
        n=text.count(old)
        if n != 1:
            raise SystemExit(f'{rel}: expected 1 exact target, found {n}: {old[:100]!r}')
        text=text.replace(old,new,1)
    if text!=original:
        p.write_text(text,encoding='utf-8')
        changed.append(rel)
print('BILINGUAL_SYMMETRY_BATCH_31_33 changed=',len(changed))
for x in changed: print('CHANGED',x)
